mapper.update:
	UPDATE BASIL_SEC_PRD.USERS U
	   SET 
	   		U.PASS_TOKEN = #{token, jdbcType=VARCHAR},
	   		U.PASS_TOKEN_EXP = #{timeStamp, jdbcType=TIMESTAMP}
    WHERE EMAIL = #{email, jdbcType=VARCHAR}

	UPDATE BASIL_SEC_PRD.USERS U
	   SET 
	   		U.PASSWORD = #{password, jdbcType=VARCHAR}
    WHERE PASS_TOKEN = #{token, jdbcType=VARCHAR}

	UPDATE BASIL_SEC_PRD.USERS U
	   SET 
	   		U.STATUS = #{status}
    WHERE PASS_TOKEN = #{token}

	UPDATE BASIL_SEC_PRD.USERS U
	   SET 
	   		U.PASS_TOKEN = #{resetToken}
    WHERE PASS_TOKEN = #{token}
